def get_default_options():
    """Read config file and return list of options."""
    options = []
    home = os.environ.get("HOME", "")
    if home:
        rcfile = os.path.join(home, RCFILE)
        try:
            with open(rcfile) as file_handle:
                options = file_handle.read().split()
        except OSError:
            pass  # ignore if no config file found
    return options


def insert_default_options():
    """insert default options to sys.argv"""
    options = get_default_options()
    options.reverse()
    for arg in options:
        sys.argv.insert(1, arg)


# astroid utilities ###########################################################
SPECIAL = re.compile(r"^__([^\W_]_*)+__$")
PRIVATE = re.compile(r"^__(_*[^\W_])+_?$")
PROTECTED = re.compile(r"^_\w*$")


def get_visibility(name):
    """return the visibility from a name: public, protected, private or special"""
    if SPECIAL.match(name):
        visibility = "special"
    elif PRIVATE.match(name):
        visibility = "private"
    elif PROTECTED.match(name):
        visibility = "protected"

    else:
        visibility = "public"
    return visibility


ABSTRACT = re.compile(r"^.*Abstract.*")
FINAL = re.compile(r"^[^\W\da-z]*$")


def is_abstract(node):
    """return true if the given class node correspond to an abstract class
    definition
    """
    return ABSTRACT.match(node.name)


def is_final(node):
    """return true if the given class/function node correspond to final
    definition
    """
    return FINAL.match(node.name)


def is_interface(node):
    # bw compat
    return node.type == "interface"


def is_exception(node):
    # bw compat
    return node.type == "exception"


# Helpers #####################################################################

_CONSTRUCTOR = 1
_SPECIAL = 2
_PROTECTED = 4
_PRIVATE = 8
MODES = {
    "ALL": 0,
    "PUB_ONLY": _SPECIAL + _PROTECTED + _PRIVATE,
    "SPECIAL": _SPECIAL,
    "OTHER": _PROTECTED + _PRIVATE,
}
VIS_MOD = {
    "special": _SPECIAL,
    "protected": _PROTECTED,
    "private": _PRIVATE,
    "public": 0,
}


class FilterMixIn:
    """filter nodes according to a mode and nodes' visibility"""

    def __init__(self, mode):
        "init filter modes"
        __mode = 0
        for nummod in mode.split("+"):
            try:
                __mode += MODES[nummod]
            except KeyError as ex:
                print("Unknown filter mode %s" % ex, file=sys.stderr)
        self.__mode = __mode

    def show_attr(self, node):
        """return true if the node should be treated"""
        visibility = get_visibility(getattr(node, "name", node))
        return not self.__mode & VIS_MOD[visibility]


class ASTWalker:
    """a walker visiting a tree in preorder, calling on the handler:

    * visit_<class name> on entering a node, where class name is the class of
    the node in lower case

    * leave_<class name> on leaving a node, where class name is the class of
    the node in lower case
    """

    def __init__(self, handler):
        self.handler = handler
        self._cache = {}

    def walk(self, node, _done=None):
        """walk on the tree from <node>, getting callbacks from handler"""
        if _done is None:
            _done = set()
        if node in _done:
            raise AssertionError((id(node), node, node.parent))
        _done.add(node)
        self.visit(node)
        for child_node in node.get_children():
            assert child_node is not node
            self.walk(child_node, _done)
        self.leave(node)
        assert node.parent is not node

    def get_callbacks(self, node):
        """get callbacks from handler for the visited node"""
        klass = node.__class__
        methods = self._cache.get(klass)
        if methods is None:
            handler = self.handler
            kid = klass.__name__.lower()
            e_method = getattr(
                handler, "visit_%s" % kid, getattr(handler, "visit_default", None)
            )
            l_method = getattr(
                handler, "leave_%s" % kid, getattr(handler, "leave_default", None)
            )
            self._cache[klass] = (e_method, l_method)
        else:
            e_method, l_method = methods
        return e_method, l_method

    def visit(self, node):
        """walk on the tree from <node>, getting callbacks from handler"""
        method = self.get_callbacks(node)[0]
        if method is not None:
            method(node)

    def leave(self, node):
        """walk on the tree from <node>, getting callbacks from handler"""
        method = self.get_callbacks(node)[1]
        if method is not None:
            method(node)


class LocalsVisitor(ASTWalker):
    """visit a project by traversing the locals dictionary"""

    def __init__(self):
        ASTWalker.__init__(self, self)
        self._visited = set()

    def visit(self, node):
        """launch the visit starting from the given node"""
        if node in self._visited:
            return None

        self._visited.add(node)
        methods = self.get_callbacks(node)
        if methods[0] is not None:
            methods[0](node)
        if hasattr(node, "locals"):  # skip Instance and other proxy
            for local_node in node.values():
                self.visit(local_node)
        if methods[1] is not None:
            return methods[1](node)
        return None


def get_annotation_label(ann: Union[astroid.Name, astroid.Subscript]) -> str:
    """Return a printable label for an annotation node."""
    label = ""
    if isinstance(ann, astroid.Subscript):
        label = ann.as_string()
    elif isinstance(ann, astroid.Name):
        label = ann.name
    elif ann is not None:
        try:
            label = ann.as_string()
        except Exception:  # pylint: disable=broad-except
            label = ""
    return label


def _get_assignattr_annotation(node: astroid.AssignAttr):
    """Return the annotation of the argument assigned to an instance attribute,
    e.g. ``self.a = a`` in ``def __init__(self, a: str)``."""
    value = getattr(node.parent, "value", None)
    if not isinstance(value, astroid.Name):
        return None
    func = node.frame()
    if not isinstance(func, astroid.FunctionDef):
        return None
    args = func.args
    if args is None or args.args is None:
        return None
    for arg, annotation in zip(args.args or [], args.annotations or []):
        if arg.name == value.name:
            return annotation
    for arg, annotation in zip(
        args.kwonlyargs or [], args.kwonlyargs_annotations or []
    ):
        if arg.name == value.name:
            return annotation
    posonly = getattr(args, "posonlyargs", None) or []
    posonly_ann = getattr(args, "posonlyargs_annotations", None) or []
    for arg, annotation in zip(posonly, posonly_ann):
        if arg.name == value.name:
            return annotation
    return None


def get_annotation(
    node: Union[astroid.AssignAttr, astroid.AssignName]
) -> Optional[Union[astroid.Name, astroid.Subscript]]:
    """return the annotation for `node`"""
    ann = None
    if isinstance(node.parent, astroid.AnnAssign):
        ann = node.parent.annotation
    elif isinstance(node, astroid.AssignAttr):
        ann = _get_assignattr_annotation(node)
    else:
        return None
    if ann is None:
        return None

    try:
        default, *_ = node.infer()
    except (astroid.InferenceError, ValueError):
        default = ""

    label = get_annotation_label(ann)
    if label:
        if (
            getattr(default, "value", "value") is None
            and not label.startswith("Optional")
        ):
            label = f"Optional[{label}]"
        ann.name = label
    return ann


def infer_node(node: Union[astroid.AssignAttr, astroid.AssignName]) -> set:
    """Return a set containing the node annotation if it exists
    otherwise return a set of the inferred types using the NodeNG.infer method"""
    ann = get_annotation(node)
    if ann:
        return {ann}
    try:
        return set(node.infer())
    except astroid.InferenceError:
        return set()

